import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"ChatGPT Chrome 扩展","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/codex/codex-chrome.md","filePath":"zh/products/ai-coding/codex/codex-chrome.md","lastUpdated":1787107158000}'),h={name:"zh/products/ai-coding/codex/codex-chrome.md"};function l(d,t,n,s,i,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="chatgpt-chrome-扩展" tabindex="-1">ChatGPT Chrome 扩展 <a class="header-anchor" href="#chatgpt-chrome-扩展" aria-label="Permalink to &quot;ChatGPT Chrome 扩展&quot;">​</a></h1><blockquote><p>这是一份<strong>教程</strong>——让 ChatGPT 驱动<strong>你的</strong> Chrome 配置，从而操作你已经登录的网站。把每个页面都当不可信上下文。允许 Agent 继续之前，先审这个站。</p><p>官方落地页：<a href="https://learn.chatgpt.com/codex/chrome-extension" target="_blank" rel="noreferrer">learn.chatgpt.com/codex/chrome-extension</a>。文档：<a href="https://learn.chatgpt.com/docs/chrome-extension" target="_blank" rel="noreferrer">Chrome extension</a>。</p></blockquote><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需要</th><th>要求</th></tr></thead><tbody><tr><td>浏览器</td><td><strong>只支持 Google Chrome</strong>。其它 Chromium 浏览器不行</td></tr><tr><td>桌面</td><td>带 Work 或 Codex 的 <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT 桌面应用</a></td></tr><tr><td>商店项</td><td><a href="https://chromewebstore.google.com/detail/chatgpt/hehggadaopoacecdllhhajmbjkdcmajg" target="_blank" rel="noreferrer">ChatGPT Chrome 扩展</a></td></tr></tbody></table><p><strong>学习目标</strong>：装好插件 + 扩展；在当前标签开侧栏对话；从 Work / Codex 调用 <code>@Chrome</code>；配置允许 / 阻止列表；分清 Chrome 和内置浏览器。</p><p><strong>非目标</strong>：Atlas（2026-08-09 已停）；Cloud Browser 登录（它用不了你的 cookie）；第二份桌面 Codex 教程（<a href="./codex-ai.html">产品线</a>）。</p><h2 id="三种浏览器-各干一件事" tabindex="-1">三种浏览器，各干一件事 <a class="header-anchor" href="#三种浏览器-各干一件事" aria-label="Permalink to &quot;三种浏览器，各干一件事&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>是什么</th><th>何时用</th></tr></thead><tbody><tr><td><strong>Chrome 扩展</strong></td><td>控制<strong>你的</strong> Chrome，含已登录标签</td><td>LinkedIn、Salesforce、Gmail、内部工具</td></tr><tr><td><strong>内置浏览器</strong>（<code>@Browser</code>）</td><td>桌面应用里单独的 ChatGPT 配置</td><td>localhost 预览、调研、别碰你的 Chrome</td></tr><tr><td><strong>Work 云端浏览器</strong></td><td>网页上托管的、未登录浏览器</td><td>公开页面；没有本地标签或密码</td></tr></tbody></table><p>任务中途可以换工具：有专用集成就用<strong>插件</strong>，要你的登录态就用 <strong>Chrome</strong>，localhost 用<strong>内置浏览器</strong>。</p><p>内置浏览器文档：<a href="https://learn.chatgpt.com/docs/browser" target="_blank" rel="noreferrer">Browser</a>。Atlas 已停，见 <a href="./">学习地图</a>。</p><h2 id="第-1-步-—-安装" tabindex="-1">第 1 步 — 安装 <a class="header-anchor" href="#第-1-步-—-安装" aria-label="Permalink to &quot;第 1 步 — 安装&quot;">​</a></h2><p>桌面应用里打开 <strong>Plugins</strong>，安装 <strong>Chrome</strong>。按流程：</p><ol><li>安装 <a href="https://chromewebstore.google.com/detail/chatgpt/hehggadaopoacecdllhhajmbjkdcmajg" target="_blank" rel="noreferrer">Chrome 扩展</a>。</li><li>批准 Chrome 权限提示。</li><li>打开 Chrome，确认 ChatGPT 侧栏能加载。</li></ol><p>必须用<strong>装着扩展的那个 Chrome 配置</strong>。换配置就要再装一次。</p><h2 id="第-2-步-—-在页面旁边聊" tabindex="-1">第 2 步 — 在页面旁边聊 <a class="header-anchor" href="#第-2-步-—-在页面旁边聊" aria-label="Permalink to &quot;第 2 步 — 在页面旁边聊&quot;">​</a></h2><ol><li>打开那个页面。</li><li>点工具栏或 <strong>Extensions</strong> 里的 ChatGPT。macOS：<code>Cmd+Shift+.</code>。</li><li>问页面，或给一个任务。</li></ol><p>面板跟着这个标签。Chrome 里开的会话会出现在 ChatGPT 应用，应用里的最近会话也能在 Chrome 打开。</p><p>点名一个打开的标签，或把选中的文字带进对话。右键 <strong>Ask ChatGPT</strong> 从页面开始。</p><p>YouTube 上，有字幕时可以用带时间戳的转写。转写仍是不可信上下文。</p><h2 id="第-3-步-—-从-chatgpt-开-chrome-任务" tabindex="-1">第 3 步 — 从 ChatGPT 开 Chrome 任务 <a class="header-anchor" href="#第-3-步-—-从-chatgpt-开-chrome-任务" aria-label="Permalink to &quot;第 3 步 — 从 ChatGPT 开 Chrome 任务&quot;">​</a></h2><p>开一条 <strong>Work</strong> 或 <strong>Codex</strong> 会话。任务需要已登录站点时，ChatGPT 会用 Chrome。也可以显式写：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Chrome open Salesforce and update the account from these call notes.</span></span></code></pre></div><p>Chrome 没开的话，ChatGPT 可以打开它。任务跑在 Chrome <strong>标签组</strong>里。</p><h2 id="控制网站访问" tabindex="-1">控制网站访问 <a class="header-anchor" href="#控制网站访问" aria-label="Permalink to &quot;控制网站访问&quot;">​</a></h2><p>默认按<strong>主机名</strong>（<code>example.com</code>）先问再动手。</p><table tabindex="0"><thead><tr><th>选项</th><th>效果</th></tr></thead><tbody><tr><td><strong>Allow once</strong></td><td>只这一次</td></tr><tr><td><strong>Allow for this site</strong></td><td>这个主机不再问</td></tr><tr><td><strong>Allow for all sites</strong></td><td>不再按站询问。风险升高</td></tr><tr><td><strong>Decline</strong></td><td>不用这个站</td></tr></tbody></table><p>列表在桌面应用：<strong>Settings → Computer Use → Google Chrome → Manage</strong>。允许列表 = 不问。阻止列表 = 不用。从任一列表拿掉域名，就回到「再问一次」。</p><p><strong>Allow for all sites</strong> 表示访问网站前不再确认。只有你信任 Agent 能碰这个 Chrome 配置里的任何标签时才选。</p><p><strong>浏览器历史</strong>是另一条升高风险的单独询问。历史可能含内部 URL、搜索词、已登录设备上的活动。访问范围限于这次请求。历史<strong>没有</strong> always-allow。</p><h2 id="数据与权限" tabindex="-1">数据与权限 <a class="header-anchor" href="#数据与权限" aria-label="Permalink to &quot;数据与权限&quot;">​</a></h2><p>Chrome 可能要调试器、全站数据、已登录设备上的历史、通知、书签、下载、原生消息、标签组。这些能力是为了跑浏览器工作流。ChatGPT 仍用自己的确认、允许列表和阻止列表。</p><p>Memories 跟随你的 Memories 设置。</p><p>OpenAI <strong>不会</strong>单独存一份完整的 Chrome 操作记录。只有进入会话上下文的浏览活动才会被保存（文本、截图、工具调用、摘要）。适用你的 ChatGPT 数据控制。除非你在场审每一条提示，否则不要把密钥送进浏览器任务。</p><h2 id="排错" tabindex="-1">排错 <a class="header-anchor" href="#排错" aria-label="Permalink to &quot;排错&quot;">​</a></h2><p>ChatGPT 连不上 Chrome 时：</p><ol><li>确认主机不在阻止列表。</li><li>更新你还留着的每一份 ChatGPT / Codex 桌面应用。</li><li>关侧栏，重启 Chrome，再开扩展。提示缺 native host 就卸了重装 Chrome 插件。</li><li>应用里切到 <strong>Work</strong> 或 <strong>Codex</strong>。确认 Chrome 插件是开的。</li><li>用装着扩展的那个 Chrome 配置。</li><li>新开一条 Work 或 Codex 会话。</li><li>重启桌面应用；最后手段是卸扩展再走一遍安装。</li><li>侧栏能开但 Chrome 任务失败：<code>/feedback</code> 并带上 chat ID。</li></ol><p>要从磁盘上传文件：Chrome → 扩展 <strong>Details → Allow access to file URLs</strong>，再重试任务。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>陷阱</th><th>结果</th><th>改做</th></tr></thead><tbody><tr><td>用 Edge / Arc / Brave</td><td>扩展不受支持</td><td>Google Chrome</td></tr><tr><td>在个人配置上允许所有站点</td><td>Agent 能碰银行 / 邮箱 / 管理后台</td><td>按站允许；单独开一个配置</td></tr><tr><td>想 always-allow 历史</td><td>官方就不提供</td><td>只批这一次请求</td></tr><tr><td>指望云端浏览器看见 Gmail</td><td>云端浏览器是未登录的</td><td>用这个扩展，或用插件</td></tr><tr><td><code>@Chrome</code> 和 <code>@Browser</code> 搞混</td><td>配置错，缺 localhost 或 cookie</td><td><code>@Browser</code> = 内置；<code>@Chrome</code> = 你的 Chrome</td></tr></tbody></table><h2 id="实际用例" tabindex="-1">实际用例 <a class="header-anchor" href="#实际用例" aria-label="Permalink to &quot;实际用例&quot;">​</a></h2><p>一个前端 bug 只在你已登录的 staging 后台复现。开 Codex 会话，<code>@Chrome</code> 那个标签，让它走失败路径，然后在本地改组件。工资和密码管理标签不要放在同一个 Chrome 配置里。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ol><li>内置浏览器和页面批注 → <a href="https://learn.chatgpt.com/docs/browser" target="_blank" rel="noreferrer">Browser</a></li><li>桌面 Computer Use（不止 Chrome） → <a href="https://learn.chatgpt.com/docs/computer-use" target="_blank" rel="noreferrer">Computer Use</a></li><li>托管公开页 → <a href="./sites.html">Sites</a></li></ol><h2 id="官方来源" tabindex="-1">官方来源 <a class="header-anchor" href="#官方来源" aria-label="Permalink to &quot;官方来源&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/codex/chrome-extension" target="_blank" rel="noreferrer">Chrome extension（落地页）</a></li><li><a href="https://learn.chatgpt.com/docs/chrome-extension" target="_blank" rel="noreferrer">Chrome extension（文档）</a></li><li><a href="https://chromewebstore.google.com/detail/chatgpt/hehggadaopoacecdllhhajmbjkdcmajg" target="_blank" rel="noreferrer">Chrome Web Store</a></li><li><a href="https://help.openai.com/en/articles/20001277-using-the-built-in-browser-in-the-chatgpt-desktop-app" target="_blank" rel="noreferrer">内置浏览器（帮助）</a></li><li><a href="https://learn.chatgpt.com/docs/browser" target="_blank" rel="noreferrer">Browser</a></li><li><a href="https://learn.chatgpt.com/docs/computer-use" target="_blank" rel="noreferrer">Computer Use</a></li></ul>',45)])])}const f=e(h,[["render",l]]);export{b as __pageData,f as default};
